                    let numMilik = parseFloat(String(vMilik).replace(',', '.')) || 0;
                    let numHgb = parseFloat(String(vHgb).replace(',', '.')) || 0;
                    let numPakai = parseFloat(String(vPakai).replace(',', '.')) || 0;
