                            rowsData[currentYear]['guguk_panjang_unit'] = inputs[0].value.trim();
                            rowsData[currentYear]['guguk_panjang_panjang'] = inputs[1].value.trim();
                        } else if (text.includes('mandiangin') && inputs.length >= 2) {
